import z3
import itertools
import time
start = time.time()
n = 24
s = z3.Solver()
e_vars = {}
for i in range(n):
    for j in range(i+1, n):
        e_vars[(i, j)] = z3.Bool(f'e_{i}_{j}')
def get_e(u, v):
    if u > v:
        u, v = v, u
    return e_vars[(u, v)]
for v in range(n):
    inc = [get_e(v, w) for w in range(n) if w != v]
    deg = z3.Sum([z3.If(x, 1, 0) for x in inc])
    s.add(deg >= 4)
    s.add(deg <= 7)
for a, b, c in itertools.combinations(range(n), 3):
    s.add(z3.Or(z3.Not(get_e(a, b)), z3.Not(get_e(a, c)), z3.Not(get_e(b, c))))
for a, b in itertools.combinations(range(n), 2):
    others = [c for c in range(n) if c != a and c != b]
    for c1, c2 in itertools.combinations(others, 2):
        ea_c1 = get_e(a, c1)
        ea_c2 = get_e(a, c2)
        eb_c1 = get_e(b, c1)
        eb_c2 = get_e(b, c2)
        s.add(z3.Or(z3.Not(ea_c1), z3.Not(ea_c2), z3.Not(eb_c1), z3.Not(eb_c2)))
print("Constraints added, solving...")
res = s.check()
print(res)
if str(res) == 'sat':
    m = s.model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if m.evaluate(get_e(i, j)):
                edges.append((i, j))
    print("Number of edges:", len(edges))
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    def find_girth():
        min_g = 100
        for start in range(n):
            dist = [-1] * n
            dist[start] = 0
            parent = [-1] * n
            q = [start]
            qi = 0
            while qi < len(q):
                u = q[qi]
                qi += 1
                for v in adj[u]:
                    if v == parent[u]:
                        continue
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif dist[v] >= dist[u]:  # to avoid parent
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < min_g:
                            min_g = cycle_len
                            if min_g < 6:
                                return min_g
        return min_g
    g = find_girth()
    print("Girth:", g)
    print("Edges:", edges)
print("Time taken:", time.time() - start)

import random
import time
start = time.time()
random.seed(42)
n = 24
max_tries = 10000
found = False
for trial in range(max_tries):
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if random.random() < 0.28:
                edges.append((i, j))
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    degs = [len(l) for l in adj]
    if min(degs) < 4 or max(degs) > 7:
        continue
    def has_short():
        for start in range(n):
            dist = [-1] * n
            dist[start] = 0
            parent = [-1] * n
            q = [start]
            qi = 0
            while qi < len(q):
                u = q[qi]
                qi += 1
                for v in adj[u]:
                    if v == parent[u]: continue
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif dist[v] >= dist[u]:
                        cycle = dist[u] + dist[v] + 1
                        if cycle < 6:
                            return True
        return False
    if not has_short():
        found = True
        print("Found on trial", trial)
        print("Edges:", sorted(edges))
        print("Degrees:", sorted(degs))
        break
if not found:
    print("Not found in", max_tries, "tries")
print("Time taken:", time.time() - start)
